// Build native Chromium-style items from Electron's context-menu metadata.
// Site-defined canvas menus keep their own handlers; no document event override.
export function browserContextMenu({page,params:p,openTab,clipboard,savePage}){
 const items=[],add=(label,click,enabled=true)=>items.push({label,click,enabled}),separator=()=>{if(items.length&&items.at(-1).type!=='separator')items.push({type:'separator'});};
 if(p.linkURL){add('在新签页中打开链接',()=>openTab(p.linkURL));add('链接另存为…',()=>page.downloadURL(p.linkURL));add('复制链接地址',()=>clipboard.writeText(p.linkURL));separator();}
 if(p.mediaType==='image'||p.mediaType==='canvas'){
  if(p.srcURL){add('在新签页中打开图片',()=>openTab(p.srcURL));add('图片另存为…',()=>page.downloadURL(p.srcURL));add('复制图片地址',()=>clipboard.writeText(p.srcURL));}
  add('复制图片',()=>page.copyImageAt(p.x,p.y),!!p.hasImageContents);separator();
 }
 if(['audio','video'].includes(p.mediaType)&&p.srcURL){add('媒体另存为…',()=>page.downloadURL(p.srcURL));add('复制媒体地址',()=>clipboard.writeText(p.srcURL));separator();}
 if(p.isEditable){for(const [label,method,flag]of [['撤销','undo','canUndo'],['重做','redo','canRedo'],['剪切','cut','canCut'],['复制','copy','canCopy'],['粘贴','paste','canPaste'],['粘贴为纯文本','pasteAndMatchStyle','canPaste'],['全选','selectAll','canSelectAll']])add(label,()=>page[method](),!!p.editFlags?.[flag]);separator();}
 else if(p.selectionText){add('复制',()=>page.copy());add('搜索“'+p.selectionText.slice(0,24)+'”',()=>openTab('https://www.google.com/search?q='+encodeURIComponent(p.selectionText)));separator();}
 add('后退',()=>page.navigationHistory.goBack(),page.navigationHistory.canGoBack());add('前进',()=>page.navigationHistory.goForward(),page.navigationHistory.canGoForward());add('重新加载',()=>page.reload());separator();
 add('网页另存为…',savePage);add('打印…',()=>page.print({silent:false}));add('检查',()=>page.inspectElement(p.x,p.y));
 return items;
}

