  target.innerHTML='<h3>账号凭证库</h3><p>一账号一空间 · 网页登录与模型授权分开核验</p><div class="notice">原网页使用独立持久空间，正常关闭会保存会话；平台过期或安全验证仍需重新登录。CLI 授权与一键模型绑定尚未接通。</div>'+s.accounts.filter(a=>!a.archivedAt).map(a=>{
   const platform=s.platforms.find(p=>p.id===a.platform)?.name||new URL(a.origin).hostname;
   return `<section class="vault-account" data-vault-account="${h(a.id)}"><div class="vault-account-identity"><span class="vault-platform">${h(platform)}</span><strong>${h(a.remark||a.accountName||platform+'账号')}</strong>${a.remark&&a.accountName?`<small>${h(a.accountName)}</small>`:''}<span class="vault-login" data-state="${h(a.observation==='unknown'?'unknown':a.loginState)}">${h(vaultLoginLabel(a))}</span><small>CLI 未授权</small></div><div class="vault-account-body"><form data-vault-remark="${h(a.id)}" class="setting-inline"><label>文字备注<input name="remark" maxlength="80" value="${h(a.remark)}" placeholder="为此账号添加备注"></label><button type="submit">保存备注</button></form><div class="vault-account-actions"><button data-vault-action="open" data-id="${h(a.id)}" ${s.desktopAvailable?'':'disabled'}>打开原网页</button><button data-vault-action="verify" data-id="${h(a.id)}" ${s.desktopAvailable?'':'disabled'}>核验账号</button><button disabled title="受保护 CLI 接线尚未完成">授权并关联模型</button><button data-vault-action="archive" data-id="${h(a.id)}">归档</button></div><p class="vault-account-message">${h(a.message||'登录完成后保持网页打开，设置会自动更新；若未识别，请展开原网页个人账号菜单。')}</p></div></section>`;
  }).join('')+`<form data-vault-add class="setting-block"><h4>新增账号空间</h4><label>平台<select name="platform">${s.platforms.map(p=>`<option value="${p.id}">${h(p.name)}</option>`).join('')}<option value="custom">其他 HTTPS 网站</option></select></label><label data-vault-custom hidden>自定义网站<input name="origin" type="url" disabled placeholder="https://example.com"></label><button type="submit">新建登录入口</button></form>`+(s.accounts.some(a=>a.archivedAt)?'<details><summary>已归档账号</summary>'+s.accounts.filter(a=>a.archivedAt).map(a=>`<p>${h(a.remark||a.platform)} <button data-vault-action="restore" data-id="${h(a.id)}">恢复账号空间</button></p>`).join('')+'</details>':'')+'<output data-vault-status role="status" aria-live="polite"></output>';
  status(notice);
 }
 async function poll(){if(!target.isConnected)return;try{if(!busy&&!target.querySelector('input:focus,select:focus'))await render({refresh:true});}catch{status('状态核验暂时不可用，原账号空间保留，可打开原网页检查。');}finally{if(target.isConnected)setTimeout(poll,5000);}}
 async function run(fn){if(busy)return;busy=true;status('正在处理…');try{const r=await fn();await render();status(r?.message||'已保存');}catch(e){status(e.message);}finally{busy=false;}}
 target.onchange=e=>{if(!e.target.matches('[data-vault-add] [name=platform]'))return;const custom=e.target.value==='custom',label=target.querySelector('[data-vault-custom]'),input=label.querySelector('input');label.hidden=!custom;input.disabled=!custom;input.required=custom;};
 target.onsubmit=e=>{const f=e.target;if(!f.matches('[data-vault-add],[data-vault-remark]'))return;e.preventDefault();void run(async()=>{const b=Object.fromEntries(new FormData(f));if(f.dataset.vaultRemark)return api('remark',{...b,accountId:f.dataset.vaultRemark});const r=await api('add',b);await render();if(r.desktopAvailable)return api('open',{accountId:r.account.id});return r;});};
 target.onclick=e=>{const b=e.target.closest('[data-vault-action]');if(!b)return;void run(async()=>{const action=b.dataset.vaultAction,accountId=b.dataset.id;if(['archive','restore'].includes(action)){const answer=await c.modal(action==='archive'?'归档账号':'恢复账号','<p>归档仅从当前列表隐藏，之后可以恢复。登录空间会保留，不删除凭据，也不修改现有模型配置。</p>',[['取消','cancel'],['确认','ok']]);if(answer.value!=='ok')return;}if(action==='verify'){
   for(;;){status('正在核验当前账号的网页登录与会话落盘状态…');const result=await api('verify',{accountId}),view=vaultVerificationDialog(result);await render();const answer=await c.modal(view.title,view.html,view.buttons);if(answer.value==='verify')continue;if(answer.value==='open')return api('open',{accountId});return result;}
  }return api(action,{accountId,confirmed:true});});};
 target.innerHTML='<h3>账号凭证库</h3><output data-vault-status role="status">正在读取本地账号空间…</output>';
 try{await render();}catch(e){status(e.message);}setTimeout(poll,5000);
}

