const h=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const labels={passed:'已通过',action_required:'需要操作',unknown:'待核验',not_authorized:'未授权'};
export function vaultVerificationDialog(result){
 const v=result.verification||{},blocked=v.blockedNavigation||[];
 return {title:'账号核验结果',html:`<div data-vault-verification><p>${h(v.accountName||'尚未取得可见账号名称')}</p><small>核验时间：${h(result.checkedAt||'未返回')}</small>${(v.checks||[]).map(row=>`<section class="setting-block"><strong>${h(row.label)} · ${h(labels[row.state]||'待核验')}</strong><p>${h(row.message)}</p></section>`).join('')}${blocked.length?'<section class="notice"><strong>发现未放行的网页跳转</strong><p>以下仅显示域名，不包含授权参数。安全白名单需核实后接入，未自动扩大权限。</p>'+blocked.map(row=>'<p>'+h(row.origin)+'</p>').join('')+'</section>':''}<p>核验不会发送生成任务，也不会替换模型凭据。</p></div>`,buttons:[['关闭','close'],['打开此账号原网页','open'],['重新核验','verify']]};
}
